import { RendererCanvas } from './base/RendererCanvas';
import { Vector3, fieldAttractors, allAttractors, fieldComposite } from './base/Vector3';

export class Solution extends RendererCanvas {

	vectorFieldVisualization: VectorFieldVisualization;

	constructor(id: string) {
		super(document.getElementById(id) as HTMLDivElement);
		this.ctx.translate(this.ctx.canvas.width * 0.5, this.ctx.canvas.height * 0.5);
		// this.clear = () => { return 0 }
		this.init();
	}
	public init() {
		this.vectorFieldVisualization = new VectorFieldVisualization()
		this.start();
	}
	public render(ctx: CanvasRenderingContext2D): void {
		this.vectorFieldVisualization.draw(ctx)

	}
	public mouseDown(x: number, y: number): void {
		x += - this.ctx.canvas.width * 0.5
		y += - this.ctx.canvas.height * 0.5
		this.vectorFieldVisualization.mouseDown(x,y);
	}
	public mouseMove(x: number, y: number): void {
		x += - this.ctx.canvas.width * 0.5
		y += - this.ctx.canvas.height * 0.5
		this.vectorFieldVisualization.mouseMove(x,y);
	}
}

class VectorFieldVisualization {
	a: Vector3[] = []; // attractors
	s: number[] = []; // strengths
	
	x0=-300.0;
	x1=300.0;
	y0=-300.0;
	y1=300.0;

	rx=50;
	ry=50;

	mouseX: number = 0;
	mouseY: number = 0;


	constructor() {

		this.a.push(new Vector3());
		this.s.push(20.0);
	}
	mouseMove(x: number, y: number) {
		this.mouseX = x;
		this.mouseY = y;
	}
	mouseDown(x: number, y: number ) {
		// if (e.button === 0) { // left click
			this.s.push(20.0);
		// } else { // right click
		// 	this.s.push(-20.0);
		// }
		
		const mousep = new Vector3(x, y, 0.0);
		this.a.push(mousep);
	}
	allAttractors(fieldPoint: Vector3): Vector3 {
		const df = new Vector3();
		
		for (let k = 0; k < this.a.length; ++k) {
			df.add(fieldComposite(fieldPoint, this.a[k], this.s[k] * 0.2, this.s[k]));
		}
		
		return df;
	}

	drawCurve(ctx: CanvasRenderingContext2D, p0: Vector3, steps: number, ds: number): void {
		const p = new Vector3();
		p.set(p0);
		
		ctx.beginPath();
		ctx.moveTo(p.x, p.y);
		
		for (let i = 0; i < steps; ++i) {
			ctx.lineTo(p.x, p.y);
			const fv = this.allAttractors(p);
			fv.normalize();
			fv.mult(ds);
			p.add(fv);
		}
		
		ctx.stroke();
	}

	drawFieldVectors(ctx: CanvasRenderingContext2D): void {
		
		const dx = (this.x1 - this.x0) / (this.rx - 1.0);
		const dy = (this.y1 - this.y0) / (this.ry - 1.0);
		
		const mousep = new Vector3(this.mouseX, this.mouseY, 0.0);
		this.a[0] = mousep;
		const p = new Vector3();
		
		ctx.lineWidth = 1;
		
		for (let j = 0; j < this.ry; ++j) {
			p.y = this.y0 + j * dy;
			for (let i = 0; i < this.rx; ++i) {
				p.x = this.x0 + i * dx;
				
				const df = this.allAttractors(p);
				
				ctx.strokeStyle = 'rgba(0, 0, 0, 0.4)';
				ctx.beginPath();
				ctx.moveTo(p.x, p.y);
				
				const p1 = Vector3.add(p, df);
				ctx.lineTo(p1.x, p1.y);
				ctx.stroke();
			}
		}
	}

	drawFieldLines(ctx: CanvasRenderingContext2D): void {
		
		const dx = (this.x1 - this.x0) / (this.rx - 1.0);
		const dy = (this.y1 - this.y0) / (this.ry - 1.0);
		
		const mousep = new Vector3(this.mouseX, this.mouseY, 0.0);
		this.a[0] = mousep;
		const p = new Vector3();
		
		// Draw main curves from mouse position
		ctx.lineWidth = 3;
		ctx.strokeStyle = 'rgba(255, 0, 0, 0.4)';
		this.drawCurve(ctx, mousep, 500, 2.0);
		this.drawCurve(ctx, mousep, 500, -2.0);
		
		// Draw grid of curves
		ctx.lineWidth = 1;
		ctx.strokeStyle = 'rgba(0, 0, 0, 0.4)';
		
		for (let j = 0; j < this.ry; j += 5) {
			p.y = this.y0 + j * dy;
			for (let i = 0; i < this.rx; i += 5) {
				p.x = this.x0 + i * dx;
				
				this.drawCurve(ctx, p, 150, 5.0);
				this.drawCurve(ctx, p, 150, -5.0);
			}
		}
	}

	draw(ctx: CanvasRenderingContext2D): void {
		// background
		ctx.fillStyle = 'white';
		ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
		
		this.drawFieldVectors(ctx);
		this.drawFieldLines(ctx);
	}
}